INSERT INTO products (id,category_id,subcategory_id,brand_id,name,slug,description,price,sale_price,stock,rating,rating_count,gender,colors,sizes,shades,tryon_type,tryon_region,is_published,created_at) VALUES
(1,1,1,1,'Camel Wool Trench Coat','camel-wool-trench-coat','A timeless double-breasted trench in a heavyweight wool blend with a storm flap, belted waist and a relaxed, structured drape.',449,NULL,24,4.8,212,'women','["Camel","Stone","Black"]','["XS","S","M","L","XL"]','[]','garment','torso_long',1,DATE_SUB(NOW(), INTERVAL 22 DAY)),
(2,1,2,2,'Army Green Puffer Jacket','army-green-puffer-jacket','Lightweight recycled-fill puffer with a quilted body, ribbed cuffs and a high collar. Warm, packable and water resistant.',229,189,24,4.6,341,'unisex','["Army Green","Black","Navy"]','["XS","S","M","L","XL"]','[]','garment','torso',1,DATE_SUB(NOW(), INTERVAL 21 DAY)),
(3,1,2,2,'Indigo Denim Trucker Jacket','indigo-denim-trucker-jacket','Classic trucker cut in rigid 12oz indigo denim with chest pockets and contrast stitching that softens beautifully with wear.',119,NULL,24,4.5,187,'unisex','["Indigo","Washed Blue"]','["XS","S","M","L","XL"]','[]','garment','torso',1,DATE_SUB(NOW(), INTERVAL 20 DAY)),
(4,1,2,3,'Olive Bomber Jacket','olive-bomber-jacket','Satin-finish bomber with ribbed collar, cuffs and hem and a clean zip front. A wardrobe staple for every season.',159,NULL,24,4.4,98,'men','["Olive","Black"]','["XS","S","M","L","XL"]','[]','garment','torso',1,DATE_SUB(NOW(), INTERVAL 19 DAY)),
(5,1,2,1,'Dark Brown Leather Biker Jacket','dark-brown-leather-biker-jacket','Full-grain lambskin biker with asymmetric zip, quilted shoulders and a satin lining. Built to last for decades.',399,349,24,4.9,156,'unisex','["Dark Brown","Black"]','["XS","S","M","L","XL"]','[]','garment','torso',1,DATE_SUB(NOW(), INTERVAL 18 DAY)),
(6,1,1,1,'Black Wool Overcoat','black-wool-overcoat','A sharply tailored single-breasted overcoat in a dense Italian wool blend with notch lapels and hidden buttons.',379,NULL,24,4.7,134,'men','["Black","Charcoal"]','["XS","S","M","L","XL"]','[]','garment','torso_long',1,DATE_SUB(NOW(), INTERVAL 17 DAY)),
(7,1,3,3,'White Linen Shirt','white-linen-shirt','Breathable stonewashed linen shirt with a relaxed fit and mother-of-pearl buttons. Effortless from beach to dinner.',79,NULL,24,4.3,76,'unisex','["White","Sky","Sand"]','["XS","S","M","L","XL"]','[]','garment','torso',1,DATE_SUB(NOW(), INTERVAL 16 DAY)),
(8,1,4,4,'Floral Summer Dress','floral-summer-dress','A flowing midi dress with a cinched waist, soft V-neckline and a hand-drawn floral print on lightweight viscose.',129,NULL,24,4.6,203,'women','["Rose","Cream"]','["XS","S","M","L","XL"]','[]','garment','torso_dress',1,DATE_SUB(NOW(), INTERVAL 15 DAY)),
(9,1,5,2,'Charcoal Hoodie','charcoal-hoodie','Heavyweight brushed-back cotton fleece hoodie with a kangaroo pocket, double-lined hood and ribbed trims.',89,NULL,24,4.5,410,'unisex','["Charcoal","Heather Grey","Black"]','["XS","S","M","L","XL"]','[]','garment','torso',1,DATE_SUB(NOW(), INTERVAL 14 DAY)),
(10,1,6,3,'Beige Knit Sweater','beige-knit-sweater','Chunky merino-blend knit with a relaxed crew neck and ribbed finishes for all-day cosy comfort.',99,NULL,24,4.4,122,'women','["Beige","Oat","Forest"]','["XS","S","M","L","XL"]','[]','garment','torso',1,DATE_SUB(NOW(), INTERVAL 13 DAY)),
(11,2,7,5,'Velvet Matte Lipstick','velvet-matte-lipstick','Intense, long-wear matte colour in a creamy, comfortable formula enriched with vitamin E. Available in five flattering shades.',14,NULL,80,4.7,1240,'women','[]','[]','[{"name":"Ruby Red","hex":"#b3122c"},{"name":"Rosewood","hex":"#a2495c"},{"name":"Coral Pop","hex":"#e2584a"},{"name":"Nude Mauve","hex":"#b5776f"},{"name":"Berry Wine","hex":"#7a1d3d"}]','face_makeup','lips',1,DATE_SUB(NOW(), INTERVAL 12 DAY)),
(12,2,8,6,'Skin Fit Liquid Foundation','skin-fit-liquid-foundation','Lightweight, buildable coverage with a natural skin-like finish that lasts up to 12 hours.',12,9.5,80,4.4,860,'women','[]','[]','[{"name":"Natural Beige","hex":"#d9a98a"},{"name":"Warm Sand","hex":"#c68e6b"},{"name":"Deep Honey","hex":"#a56b47"}]','face_makeup','face',1,DATE_SUB(NOW(), INTERVAL 11 DAY)),
(13,2,9,7,'Soft Glow Cheek Blush','soft-glow-cheek-blush','Silky powder blush with buildable colour and a natural, satin glow that blends effortlessly.',11,NULL,80,4.3,530,'women','[]','[]','[{"name":"Peach Glow","hex":"#f08a6c"},{"name":"Rose Petal","hex":"#e0708a"},{"name":"Warm Berry","hex":"#b6485f"}]','face_makeup','cheeks',1,DATE_SUB(NOW(), INTERVAL 10 DAY)),
(14,2,10,8,'Precision Liquid Eyeliner','precision-liquid-eyeliner','Ultra-fine felt tip for razor-sharp wings and bold lines. Smudge-proof and waterproof for 24 hours.',22,NULL,80,4.6,402,'women','[]','[]','[{"name":"Midnight Black","hex":"#111111"},{"name":"Espresso","hex":"#3b2418"},{"name":"Deep Navy","hex":"#16224a"}]','face_makeup','eyeliner',1,DATE_SUB(NOW(), INTERVAL 9 DAY)),
(15,2,11,9,'Sunset Eyeshadow Palette','sunset-eyeshadow-palette','Sixteen richly pigmented matte and shimmer shades for everyday looks and bold evenings alike.',67,59,80,4.8,978,'women','[]','[]','[{"name":"Copper Sunset","hex":"#b8643a"},{"name":"Smoky Plum","hex":"#6b3a58"},{"name":"Champagne","hex":"#d8b88a"}]','face_makeup','eyelids',1,DATE_SUB(NOW(), INTERVAL 8 DAY)),
(16,2,12,10,'Intense Kohl Kajal','intense-kohl-kajal','Smudge-proof, creamy kohl pencil for an intense, long-lasting look in a single stroke.',9,NULL,80,4.5,721,'women','[]','[]','[{"name":"Jet Black","hex":"#0e0e10"},{"name":"Brown","hex":"#4a2c1d"}]','face_makeup','waterline',1,DATE_SUB(NOW(), INTERVAL 7 DAY)),
(17,3,13,2,'Classic Steel Wrist Watch','classic-steel-wrist-watch','Minimalist analogue watch with a sapphire-coated crystal, quartz movement and a brushed steel case.',189,159,30,4.7,245,'unisex','["Gold","Silver"]','[]','[]','accessory','wrist',1,DATE_SUB(NOW(), INTERVAL 6 DAY)),
(18,3,14,3,'Woven Metal Bracelet','woven-metal-bracelet','A chunky woven-metal cuff bracelet with a polished finish that stacks beautifully.',59,NULL,30,4.3,118,'women','["Gold","Silver","Rose Gold"]','[]','[]','accessory','wrist',1,DATE_SUB(NOW(), INTERVAL 5 DAY)),
(19,3,15,11,'Aviator Sunglasses','aviator-sunglasses','Iconic teardrop aviators with polarised UV400 lenses and a lightweight metal frame.',129,NULL,30,4.6,312,'unisex','["Gold/Green","Silver/Grey"]','[]','[]','accessory','eyes',1,DATE_SUB(NOW(), INTERVAL 4 DAY)),
(20,3,15,11,'Round Frame Glasses','round-frame-glasses','Retro round acetate frames with blue-light filtering lenses for screen and street.',99,79,30,4.4,167,'unisex','["Black","Tortoise"]','[]','[]','accessory','eyes',1,DATE_SUB(NOW(), INTERVAL 3 DAY)),
(21,3,17,4,'Teardrop Gold Earrings','teardrop-gold-earrings','Polished teardrop drop earrings with hypoallergenic posts, lightweight enough for all-day wear.',69,NULL,30,4.8,201,'women','["Gold","Silver"]','[]','[]','accessory','ears',1,DATE_SUB(NOW(), INTERVAL 2 DAY)),
(22,3,19,3,'Everyday Baseball Cap','everyday-baseball-cap','Washed cotton twill cap with a curved brim and an adjustable strap back.',35,NULL,30,4.2,96,'unisex','["Navy","Black","Sand"]','[]','[]','accessory','head',1,DATE_SUB(NOW(), INTERVAL 1 DAY));
